"""One-use password reset through restricted HTTP and independent PostgreSQL."""

import asyncio
import shutil
from pathlib import Path

import pytest
import pytest_asyncio
from test_identity_session import A, B
from test_identity_session import identities as identities  # noqa: PLC0414
from test_lifecycle import deployment as deployment  # noqa: PLC0414
from test_lifecycle import migration, server

CODE = "K7WQ-2MZP-4HXA"
# Independent Node hashResetCode known answer; never generated by the port.
DIGEST = bytes.fromhex(
    "f9609fb684797772a50289433359af852edd3ee2471fd56adcd44e5d0b5dc7ab"
)
NEXT = "violet river stones"
URL = "/api/v1/login/password-reset"
INVALID = {"error": "that reset code is wrong or has expired", "code": "reset-invalid"}


@pytest_asyncio.fixture
async def reset(identities):
    observer, environment = identities
    environment["PASSWORD_LOGIN"] = "1"
    await observer.execute(
        """INSERT INTO identity.password_resets VALUES ('A',$1,clock_timestamp()+interval '24 hours','B');
        """,
        DIGEST,
    )
    await observer.execute("""
        INSERT INTO identity.login_aliases VALUES
            ('alice','A',false,false,clock_timestamp()+interval '24 hours'),
            ('a@example.test','A',true,false,NULL), ('bob','B',false,true,NULL);
        INSERT INTO identity.device_links VALUES (decode(repeat('ab',32),'hex'),'A',now(),now()+interval '10 min');
        INSERT INTO identity.passkeys VALUES ('preserved','A',decode('aa','hex'),0,'{}',NULL,NULL,NULL);
    """)
    return observer, environment


@pytest.mark.asyncio
async def test_reset_signs_in_consumes_once_and_revokes_only_owner(reset):
    observer, environment = reset
    async with server(environment) as client:
        response = await client.post(
            URL,
            json={
                "identifier": " Ａ@example.test ",
                "code": " k7wq 2mzp-4hxa ",
                "next": NEXT,
                "owner": "B",
            },
        )
        assert response.status_code == 200, response.text
        assert response.json() == {"user": {"id": "A", "name": "Alice", "admin": False}}
        assert response.headers["cache-control"] == "no-store"
        assert "HttpOnly" in response.headers["set-cookie"]
        assert (await client.get("/api/v1/me")).status_code == 200
        assert (
            await client.get("/api/v1/me", headers={"Cookie": "gymsid=" + A})
        ).status_code == 401
        assert (
            await client.get("/api/v1/me", headers={"Cookie": "gymsid=" + B})
        ).status_code == 200
        assert (
            await client.post(URL, json={"name": "Alice", "code": CODE, "next": NEXT})
        ).json() == INVALID
        assert (
            await client.post(
                "/api/v1/login/password", json={"name": "Alice", "password": NEXT}
            )
        ).status_code == 200
    assert await observer.fetchval("SELECT count(*) FROM identity.password_resets") == 0
    assert await observer.fetchval("SELECT count(*) FROM identity.device_links") == 0
    assert await observer.fetchval("SELECT count(*) FROM identity.passkeys") == 1
    assert [
        tuple(r)
        for r in await observer.fetch(
            "SELECT id,session_version FROM identity.users ORDER BY id"
        )
    ] == [("A", 1), ("B", 3)]
    assert tuple(
        await observer.fetchrow(
            "SELECT password_name_claim,reset_name_until FROM identity.login_aliases WHERE alias_key='alice'"
        )
    ) == (True, None)


@pytest.mark.asyncio
@pytest.mark.parametrize(
    "mutation",
    ["valid", "email", "version", "name", "disabled", "deleted", "expired", "reissued"],
)
async def test_crypto_revalidates_code_identity_and_access_without_a_database_lease(
    reset, tmp_path, mutation
):
    observer, environment = reset
    entered, release = tmp_path / "entered", tmp_path / "release"
    (tmp_path / "reset_boundary.py").write_text(f"""
import time
from pathlib import Path
from opengym_platform.identity import passwords
from opengym_platform.application import create_app
original = passwords.derive
def derive(password, material):
    if password != {NEXT!r}:
        return original(password,material)
    Path({str(entered)!r}).touch()
    deadline = time.monotonic()+8
    while not Path({str(release)!r}).exists():
        if time.monotonic()>deadline:
            raise ValueError("synthetic crypto deadline")
        time.sleep(.01)
    return original(password,material)
passwords.derive = derive
""")
    environment["PYTHONPATH"] = str(tmp_path) + ":/app/src"
    async with server(environment, factory="reset_boundary:create_app") as client:
        task = asyncio.create_task(
            client.post(
                URL, json={"email": "a@example.test", "code": CODE, "next": NEXT}
            )
        )
        try:
            async with asyncio.timeout(4):
                while not entered.exists():
                    await asyncio.sleep(0.01)
            assert not await observer.fetchval(
                "SELECT EXISTS(SELECT FROM pg_stat_activity WHERE usename='opengym_api_runtime' AND xact_start IS NOT NULL)"
            )
            changes = {
                "email": "UPDATE identity.login_aliases SET alias_key='changed@example.test' WHERE email_claim",
                "version": "UPDATE identity.users SET session_version=1 WHERE id='A'",
                "name": "UPDATE identity.users SET display_name='Changed' WHERE id='A'",
                "disabled": "UPDATE identity.users SET disabled=true WHERE id='A'",
                "deleted": "DELETE FROM identity.users WHERE id='A'",
                "expired": "UPDATE identity.password_resets SET expires_at=clock_timestamp()-interval '1 second'",
                "reissued": "UPDATE identity.password_resets SET code_digest=decode(repeat('cd',32),'hex')",
            }
            if mutation in changes:
                await observer.execute(changes[mutation])
        finally:
            release.touch()
        result = await task
        assert result.status_code == (
            200 if mutation == "valid" else 403 if mutation == "disabled" else 400
        ), result.text
        if mutation != "valid":
            assert "set-cookie" not in result.headers
            assert (
                await observer.fetchval(
                    "SELECT count(*) FROM identity.password_credentials"
                )
                == 0
            )
            assert await observer.fetchval(
                "SELECT count(*) FROM identity.password_resets"
            ) == (0 if mutation == "deleted" else 1)


@pytest.mark.asyncio
@pytest.mark.parametrize("expire", [False, True])
async def test_waiting_redemptions_recheck_expiry_and_only_one_can_commit(
    reset, expire
):
    observer, environment = reset
    async with server(environment) as client:
        async with observer.transaction():
            await observer.execute("SELECT pg_advisory_xact_lock(728323)")
            tasks = [
                asyncio.create_task(
                    client.post(URL, json={"name": "Alice", "code": CODE, "next": NEXT})
                )
                for _ in range(2)
            ]
            async with asyncio.timeout(1.8):
                while True:
                    await observer.execute("SELECT pg_stat_clear_snapshot()")
                    waiting = await observer.fetchval(
                        "SELECT count(*) FROM pg_stat_activity WHERE usename='opengym_api_runtime' AND wait_event_type='Lock' AND query LIKE '%identity.finish_reset%'"
                    )
                    if waiting == 2:
                        break
                    await asyncio.sleep(0.01)
            if expire:
                await observer.execute(
                    "UPDATE identity.password_resets SET expires_at=clock_timestamp()"
                )
        results = await asyncio.gather(*tasks)
        assert sorted(r.status_code for r in results) == (
            [400, 400] if expire else [200, 400]
        )
        assert await observer.fetchval(
            "SELECT session_version FROM identity.users WHERE id='A'"
        ) == (0 if expire else 1)
        assert await observer.fetchval(
            "SELECT count(*) FROM identity.password_credentials"
        ) == (0 if expire else 1)
        assert await observer.fetchval(
            "SELECT count(*) FROM identity.password_resets"
        ) == (1 if expire else 0)
        for r in results:
            if r.status_code == 400:
                assert r.json() == INVALID and "set-cookie" not in r.headers


@pytest.mark.asyncio
async def test_sql_failure_rolls_back_all_reset_effects_and_allows_retry(reset):
    observer, environment = reset
    await observer.execute("""
        CREATE FUNCTION public.fail_reset() RETURNS trigger LANGUAGE plpgsql AS $$
            BEGIN RAISE EXCEPTION 'private-reset-marker'; END $$;
        CREATE TRIGGER fail_reset BEFORE UPDATE OF session_version ON identity.users
            FOR EACH ROW EXECUTE FUNCTION public.fail_reset();
    """)
    async with server(environment) as client:
        body = {"name": "Alice", "code": CODE, "next": NEXT}
        result = await client.post(URL, json=body)
        assert result.status_code == 500 and result.json() == {"error": "server error"}
        assert "set-cookie" not in result.headers
        assert (
            await observer.fetchval(
                "SELECT count(*) FROM identity.password_credentials"
            )
            == 0
        )
        assert (
            await observer.fetchval("SELECT count(*) FROM identity.password_resets")
            == 1
        )
        assert (
            await observer.fetchval("SELECT count(*) FROM identity.device_links") == 1
        )
        assert (
            await observer.fetchval(
                "SELECT session_version FROM identity.users WHERE id='A'"
            )
            == 0
        )
        assert await observer.fetchval(
            "SELECT NOT password_name_claim AND reset_name_until IS NOT NULL FROM identity.login_aliases WHERE alias_key='alice'"
        )
        await observer.execute("DROP TRIGGER fail_reset ON identity.users")
        assert (await client.post(URL, json=body)).status_code == 200


@pytest.mark.asyncio
@pytest.mark.parametrize("purpose", ["email", "password", "future", "expired"])
async def test_alias_conflict_does_not_consume_code_and_only_expired_reservation_is_reclaimed(
    reset, purpose
):
    observer, environment = reset
    await observer.execute("DELETE FROM identity.login_aliases WHERE alias_key='alice'")
    await observer.execute(
        "INSERT INTO identity.users(id,display_name) VALUES ('C','Other')"
    )
    await observer.execute(
        """INSERT INTO identity.login_aliases VALUES ('alice','C',$1,$2,
        CASE WHEN $3 THEN clock_timestamp()+interval '1 day' WHEN $4 THEN clock_timestamp()-interval '1 day' END)""",
        purpose == "email",
        purpose == "password",
        purpose == "future",
        purpose == "expired",
    )
    async with server(environment) as client:
        result = await client.post(
            URL, json={"name": "Alice", "code": CODE, "next": NEXT}
        )
        assert result.status_code == (200 if purpose == "expired" else 409), result.text
        assert await observer.fetchval(
            "SELECT owner_id FROM identity.login_aliases WHERE alias_key='alice'"
        ) == ("A" if purpose == "expired" else "C")
        assert await observer.fetchval(
            "SELECT count(*) FROM identity.password_resets"
        ) == (0 if purpose == "expired" else 1)
        if purpose != "expired":
            assert result.json() == {
                "error": "another profile already signs in with this name",
                "code": "name-taken",
            }
            assert "set-cookie" not in result.headers


@pytest.mark.asyncio
async def test_validation_policy_and_wrong_codes_preserve_reset(reset):
    observer, environment = reset
    async with server(environment) as client:
        for body, expected in [
            ({}, "missing"),
            ({"name": "Alice", "code": "wrong", "next": NEXT}, "reset-invalid"),
            ({"name": "Bob", "code": CODE, "next": NEXT}, "reset-invalid"),
            ({"name": "missing", "code": CODE, "next": NEXT}, "reset-invalid"),
            ({"name": "Alice", "code": CODE, "next": "short"}, "too-short"),
            ({"name": "Alice", "code": CODE, "next": "password1234"}, "too-common"),
            ({"name": "Alice", "code": CODE, "next": "x" * 257}, "too-long"),
            (
                {"identifier": "wrong", "name": "Alice", "code": CODE, "next": NEXT},
                "reset-invalid",
            ),
        ]:
            response = await client.post(URL, json=body)
            assert response.status_code == 400 and response.json()["code"] == expected
            assert "set-cookie" not in response.headers
            assert (
                await observer.fetchval("SELECT count(*) FROM identity.password_resets")
                == 1
            )
        assert (
            await client.post(URL, json={"email": "Alice", "code": CODE, "next": NEXT})
        ).status_code == 200


@pytest.mark.asyncio
@pytest.mark.parametrize("secure", [False, True])
async def test_transport_cookie_csrf_body_limit_and_password_off(reset, secure):
    _, environment = reset
    environment["ORIGIN"] = "https://gym.example" if secure else "http://localhost:8080"
    body = {"name": "Alice", "code": CODE, "next": NEXT}
    async with server(environment) as client:
        denied = await client.post(
            URL, headers={"Origin": "https://foreign.test"}, json=body
        )
        assert denied.status_code == 403 and denied.json() == {
            "error": "cross-origin request refused"
        }
        for raw, status in [
            ("{", 400),
            ('{"x":NaN}', 400),
            ("[]", 400),
            ("x" * (5 * 1024 * 1024 + 1), 413),
        ]:
            result = await client.post(URL, content=raw)
            assert result.status_code == status and "set-cookie" not in result.headers
        result = await client.post(
            URL, headers={"Authorization": "Bearer unrelated"}, json=body
        )
        assert result.status_code == 200 and "token" not in result.json()
        cookies = result.headers.get_list("set-cookie")
        assert len(cookies) == (2 if secure else 1)
        assert cookies[0].startswith("__Host-gymsid=" if secure else "gymsid=")
        assert "HttpOnly" in cookies[0] and "SameSite=Lax" in cookies[0]
        assert ("; Secure;" in cookies[0]) == secure
        if secure:
            assert "Max-Age=0" in cookies[1]
        assert (
            await client.post("/api/login/password-reset", json=body)
        ).status_code == 404
    environment["PASSWORD_LOGIN"] = "0"
    async with server(environment) as client:
        assert (await client.post(URL, json=body)).status_code == 404


@pytest.mark.asyncio
async def test_wrong_codes_use_shared_address_budget_without_locking_target_account(
    reset,
):
    _, environment = reset
    environment["TRUST_PROXY"] = "1"
    async with server(environment) as client:
        for i in range(21):
            result = await client.post(
                URL,
                headers={"X-Forwarded-For": "192.0.2.1"},
                json={"name": "Alice", "code": str(i), "next": NEXT},
            )
            assert result.status_code == 400
        for path, body in [
            (URL, {"name": "Alice", "code": CODE, "next": NEXT}),
            ("/api/v1/login/password", {"name": "Alice", "password": NEXT}),
        ]:
            result = await client.post(
                path, headers={"X-Forwarded-For": "192.0.2.1"}, json=body
            )
            assert result.status_code == 429 and int(result.headers["retry-after"]) > 0
        # The same account is still redeemable from another address.
        assert (
            await client.post(
                URL,
                headers={"X-Forwarded-For": "192.0.2.2"},
                json={"name": "Alice", "code": CODE, "next": NEXT},
            )
        ).status_code == 200


@pytest.mark.asyncio
async def test_forward_migration_and_reset_functions_keep_runtime_restricted(
    deployment, tmp_path, monkeypatch
):
    from opengym_platform.core.database import Database, DatabaseError

    observer, environment = deployment
    previous = tmp_path / "previous"
    shutil.copytree(
        Path("/app/src/opengym_platform"),
        previous / "opengym_platform",
        ignore=shutil.ignore_patterns(
            "p003_coach.py",
            "p003_coach_lifecycle.py",
            "p003_coach_http.py",
            "p003_coach_jobs.py",
            "p002_media_gc.py",
            "p001_links.py",
            "p001_reset.py",
        ),
    )
    await migration({**environment, "PYTHONPATH": str(previous)}, "up")
    assert (
        await observer.fetchval("SELECT version_num FROM public.alembic_version")
        == "p001_passkey_manage"
    )
    await observer.execute(
        "INSERT INTO identity.users(id,display_name) VALUES ('A','Alice')"
    )
    await observer.execute(
        "INSERT INTO identity.password_resets VALUES ('A',$1,now()+interval '24 hours','historic')",
        DIGEST,
    )
    before = await observer.fetch("SELECT * FROM identity.password_resets")
    await migration(environment, "up")
    await migration(environment, "up")
    assert await observer.fetch("SELECT * FROM identity.password_resets") == before
    assert (
        await observer.fetchval("SELECT version_num FROM public.alembic_version")
        == "p003_coach_lifecycle"
    )
    functions = await observer.fetch("""SELECT p.prosecdef,p.proconfig,pg_get_userbyid(p.proowner) AS owner,
        EXISTS(SELECT FROM aclexplode(p.proacl) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE') AS public
        FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
        WHERE n.nspname='identity' AND p.proname IN ('lookup_reset','finish_reset')""")
    assert len(functions) == 2
    for row in functions:
        assert row["prosecdef"] and not row["public"]
        assert row["owner"] == "opengym_identity_executor" and row["proconfig"] == [
            "search_path=pg_catalog, pg_temp"
        ]
    for table in (
        "password_resets",
        "device_links",
        "users",
        "login_aliases",
        "password_credentials",
    ):
        assert await observer.fetchval(
            "SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid=$1::regclass",
            "identity." + table,
        )
    for key, value in environment.items():
        monkeypatch.setenv(key, value)
    monkeypatch.setenv(
        "PLATFORM_DB_PASSWORD_FILE", environment["PLATFORM_RUNTIME_PASSWORD_FILE"]
    )
    monkeypatch.delenv("PLATFORM_DB_PASSWORD", raising=False)
    database = await Database.open_platform()
    try:
        assert (
            await database.fetch("SELECT * FROM identity.lookup_reset($1)", b"short")
            == []
        )
        assert (
            await database.fetch(
                "SELECT * FROM identity.finish_reset('A',$1,'forged')", DIGEST
            )
            == []
        )
        for sql in [
            "SELECT code_digest FROM identity.password_resets",
            "UPDATE identity.users SET is_admin=true",
            "SET ROLE opengym_identity_executor",
            "CREATE TABLE identity.forbidden(id text)",
        ]:
            with pytest.raises(DatabaseError):
                await database.execute(sql)
        assert await database.fetch("SELECT id FROM identity.users") == []
    finally:
        await database.close()
